def _model_config(kv_cache_quant_algo=None):
    quantization_config = {"quant_method": "modelopt"}
    if kv_cache_quant_algo is not None:
        quantization_config["quantization"] = {
            "kv_cache_quant_algo": kv_cache_quant_algo
        }
    return SimpleNamespace(
        hf_config=SimpleNamespace(quantization_config=quantization_config)
    )


@pytest.mark.parametrize("requested", ["auto", "fp8", "fp8_e4m3"])
def test_checkpoint_kv_cache_dtype_metadata_precedence(requested):
    model_config = _model_config("FP8")

    assert resolve_kv_cache_dtype_string(requested, model_config) == "fp8_e4m3"


@pytest.mark.parametrize("requested", ["auto", "bfloat16"])
def test_checkpoint_without_kv_cache_dtype_metadata(requested):
    assert resolve_kv_cache_dtype_string(requested, _model_config()) == requested


def test_checkpoint_kv_cache_dtype_rejects_incompatible_override():
    with pytest.raises(
        ValueError,
        match=r"checkpoint declares kv_cache_quant_algo.*--kv-cache-dtype.*auto",
    ):
        resolve_kv_cache_dtype_string("bfloat16", _model_config("FP8"))


