              "ordinal": 8,
              "text": "[Document context]\nTitle: vLLM cache configuration\nSource: local vLLM issue 34752 remediation\nPath: /code/vllm/vllm/config/cache.py\nWorkspace: task/jamal-kv-cache-dtype-34752\n\n.\"\"\"\n\nkv_offloading_backend: KVOffloadingBackend = \"native\"\n    \"\"\"The backend to use for KV cache offloading. Supported backends include\n    'native' (vLLM native CPU offloading), 'lmcache'.\n    KV offloading is only activated when kv_offloading_size is set.\"\"\"\n\ndef compute_hash(self) -> str:\n        \"\"\"\n        WARNING: Whenever a new field is added to this config,\n        ensure that it is included in the factors list if\n        it affects the computation graph.\n\nProvide a hash that uniquely identifies all the configs\n        that affect the structure of the computation\n        graph from input ids/embeddings to the final hidden states,\n        excluding anything before input ids/embeddings and after\n        the final hidden states.\n        \"\"\"\n        ignored_factors = {\n            # Runtime/derived knobs that don't affect compiled graph shape\n            \"gpu_memory_utilization\",\n            \"kv_cache_memory_bytes\",\n            \"is_attention_free\",\n            \"num_gpu_blocks_override\",\n            \"enable_prefix_caching\",\n            \"prefix_caching_hash_algo\",\n            # Prefix-caching implementation detail (doesn't affect compiled graph).\n            \"prefix_match_unit\",\n            \"mamba_page_size_padded\",\n            \"skip_page_size_padded\",\n            \"user_specified_block_size\",\n            \"user_specified_mamba_block_size\",\n            \"_block_size_resolved\",\n            # Post-init/derived counters\n            \"num_gpu_blocks\",\n            \"num_cpu_blocks\",\n            \"kv_cache_size_tokens\",\n            \"kv_cache_max_concurrency\",\n            # WIP feature toggle not impacting compiled graph shape\n            \"kv_sharing_fast_prefill\",\n        }\n\nfrom vllm.config.utils import get_hash_factors, hash_factors\n\nfactors = get_hash_factors(self, ignored_factors)\n        return hash_factors(factors)\n\ndef metrics_info(self):\n        # convert cache_config to dict(key: str, value: str) for prometheus\n        # metrics info\n        return {key: str(value) for key, value in self.__dict__.items()}\n\n_block_size_resolved: bool = field(default=False, init=False)\n    \"\"\"Guard against pydantic re-running _apply_block_size_default.\"\"\"",
