def resolve_kv_cache_dtype_string(
    kv_cache_dtype: str, model_config: ModelConfig
) -> str:
    """Resolve and validate the KV-cache dtype against checkpoint metadata.

    Checkpoint KV-cache quantization metadata is a storage-format requirement,
    not a hint. ``auto`` (whether implicit or explicit) adopts that format. An
    explicit dtype is accepted only when it denotes the same format; otherwise
    it is rejected here, before cache allocation or model execution. Without
    metadata, ``auto`` remains unchanged and explicit values pass through.
    """
