    hf_cfg = getattr(model_config, "hf_config", None)
    if hf_cfg is not None:
        quant_cfg = getattr(hf_cfg, "quantization_config", None)
        if quant_cfg is not None:
            checkpoint_cache_dtype = get_kv_cache_quant_algo_string(quant_cfg)

    if checkpoint_cache_dtype in (None, "auto"):
        return kv_cache_dtype

    if kv_cache_dtype == "auto":
        return checkpoint_cache_dtype

    # ``fp8`` is the user-facing alias for E4M3, which is also the format
    # represented by ModelOpt's FP8 checkpoint metadata.
    requested_dtype = (
        "fp8_e4m3" if kv_cache_dtype == "fp8" else kv_cache_dtype
    )
