            "The checkpoint declares kv_cache_quant_algo requiring "
            f"KV cache dtype '{checkpoint_cache_dtype}', but "
            f"--kv-cache-dtype was set to '{kv_cache_dtype}'. Use "
            "--kv-cache-dtype auto (recommended) or the checkpoint dtype; "
            "non-matching overrides are not supported."
        )

    return checkpoint_cache_dtype


